// Strip HTML for text-based filtering
function stripHtml(html) {
  if (!html) return '';
  return html.replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function getCompanyMeta(itemIndex) {
  try {
    return $('Set Target Companies').itemMatching(itemIndex).json;
  } catch {
    return { name: 'Unknown', tier: 'Unknown', platform: 'greenhouse' };
  }
}

// Filter patterns
const titleWhitelist = /\b(senior|staff|principal|lead|sr\.?)\s+(software|backend|platform|infrastructure|data|analytics|cloud|ml|mlops|reliability|systems)\s*(engineer|developer|analyst|scientist)\b/i;

const titleBlacklist = /\b(junior|jr\.?|intern|associate|entry|graduate|manager|director|head\s+of|vp|chief)\b/i;

const contractPatterns = [
  /\bcontract(ing|or|-to-hire)?\b/i,
  /\bc2h\b/i,
  /\b1099\b/i,
  /\bw2\s+contract\b/i,
  /\btemp(orary|-to-perm)?\b/i,
  /(\d+)\s*(month|year)s?\s+(contract|engagement|assignment|term)/i,
  /\bproject[-\s]?based\b/i,
  /\bfixed[-\s]?term\b/i,
  /\bcontingent\b/i
];

const consultingPhrasePatterns = [
  /\bon\s+behalf\s+of\s+our\s+client/i,
  /\bend[-\s]?client\b/i,
  /our\s+client\s+(is\s+looking|is\s+seeking|requires)/i,
  /staffing\s+(partner|firm|agency)/i,
  /\bbill\s+rate\b/i,
  /\bsubcontract/i,
  /\bperm\s+placement/i,
  /\bright[-\s]?to[-\s]?hire/i
];

const strongDeSignals = [
  /\betl\b/i, /\belt\b/i, /data\s+pipelines?/i, /apache\s+airflow/i, /\bdbt\b/i,
  /apache\s+spark/i, /apache\s+kafka/i, /apache\s+flink/i,
  /data\s+warehous/i, /data\s+lake/i, /lakehouse/i, /data\s+mesh/i,
  /snowflake/i, /bigquery/i, /redshift/i, /databricks/i,
  /data\s+model/i, /dimensional\s+model/i, /data\s+quality/i,
  /streaming\s+data/i, /batch\s+process/i, /real[\s-]?time\s+data/i,
  /data\s+ingest/i, /data\s+transform/i, /data\s+orchestrat/i,
  /data\s+infrastructure/i, /data\s+platform/i
];

const mediumDeSignals = [
  /\bsql\b/i, /python.*data|data.*python/i, /aws\s+s3/i, /\bgcs\b/i,
  /data\s+governance/i, /data\s+catalog/i,
  /ml\s+pipeline/i, /feature\s+store/i, /mlops/i,
  /\bschema\b/i, /data\s+architect/i
];

const counterSignals = [
  /\breact\b/i, /\bvue\b/i, /\bangular\b/i,
  /\bios\b/i, /\bandroid\b/i, /\bswift\b/i, /\bkotlin\b/i,
  /game\s+engine/i, /\bgraphics\b/i,
  /\bcss\b/i, /ui\/ux/i, /design\s+system/i,
  /embedded\s+systems?/i, /firmware/i,
  /\basic\b/i, /\bfpga\b/i, /\brtl\b/i
];

const countMatches = (text, patterns) =>
  patterns.reduce((n, rx) => n + (rx.test(text) ? 1 : 0), 0);

// Main loop
const allItems = $input.all();
const allFilteredJobs = [];
const stats = { totalJobs: 0, kept: 0, droppedTitle: 0, droppedLocation: 0, droppedContract: 0, droppedDeFit: 0, errors: 0 };

for (let idx = 0; idx < allItems.length; idx++) {
  const item = allItems[idx];
  const companyMeta = getCompanyMeta(idx);
  const responseData = item.json;
  const company = companyMeta.name;
  const platform = companyMeta.platform;

  let jobs = [];
  if (responseData.jobs) {
    jobs = responseData.jobs;
  } else if (Array.isArray(responseData)) {
    jobs = responseData;
  } else {
    stats.errors++;
    continue;
  }

  stats.totalJobs += jobs.length;

  for (const job of jobs) {
    const normalized = platform === 'greenhouse' ? {
      title: job.title || '',
      url: job.absolute_url || '',
      location: job.location?.name || 'Unknown',
      department: job.departments?.[0]?.name || 'Unknown',
      jdText: stripHtml(job.content),
      jobId: job.id,
      postedDate: job.updated_at
    } : {
      title: job.text || '',
      url: job.hostedUrl || '',
      location: job.categories?.location || 'Unknown',
      department: job.categories?.team || job.categories?.department || 'Unknown',
      jdText: stripHtml(job.descriptionPlain || job.description || ''),
      jobId: job.id,
      postedDate: job.createdAt ? new Date(job.createdAt).toISOString() : null
    };

    if (!titleWhitelist.test(normalized.title) || titleBlacklist.test(normalized.title)) {
      stats.droppedTitle++;
      continue;
    }

    // Layer 1.5: Location must include US/USA/United States or be remote-US
const locationLower = (normalized.location || '').toLowerCase();
const isUSOrRemote = /(united states|usa|u\.s\.|us[-\s]?remote|remote.*us|us.*remote)/i.test(locationLower)
  || /\b(new york|nyc|san francisco|sf|seattle|boston|austin|chicago|los angeles|atlanta|denver|washington|virginia|texas|california|massachusetts|colorado|washington|dc)\b/i.test(locationLower);

const isExplicitlyForeign = /(india|bengaluru|bangalore|canada|toronto|vancouver|london|berlin|amsterdam|sydney|singapore|tokyo|dublin|tel aviv|warsaw|prague)/i.test(locationLower)
  && !isUSOrRemote;

if (!isUSOrRemote || isExplicitlyForeign) {
  stats.droppedLocation = (stats.droppedLocation || 0) + 1;
  continue;
}

    const titleAndJd = normalized.title + ' ' + normalized.jdText.slice(0, 1500);
    const isContract = contractPatterns.some(rx => rx.test(titleAndJd));
    const consultingHits = consultingPhrasePatterns.filter(rx => rx.test(normalized.jdText)).length;

    if (isContract || consultingHits >= 2) {
      stats.droppedContract++;
      continue;
    }

    const strongHits = countMatches(normalized.jdText, strongDeSignals);
    const mediumHits = countMatches(normalized.jdText, mediumDeSignals);
    const counterHits = countMatches(normalized.jdText, counterSignals);
    const deFitScore = (strongHits * 3) + (mediumHits * 1) - (counterHits * 2);

    if (deFitScore < 8) {
      stats.droppedDeFit++;
      continue;
    }

    allFilteredJobs.push({
      company,
      tier: companyMeta.tier || 'Unknown',
      ...normalized,
      deFitScore,
      deFitBreakdown: { strongHits, mediumHits, counterHits }
    });
    stats.kept++;
  }
}

allFilteredJobs.sort((a, b) => b.deFitScore - a.deFitScore);

console.log(`Stats: ${JSON.stringify(stats)}`);

const output = allFilteredJobs.map(j => ({ json: j }));
output.push({ json: { __stats: stats } });

return output;

const items = $input.all();
const count = items.length;
return [{
  json: {
    message: `✅ Job Hunter run complete\n\n📊 ${count} shortlisted jobs added to Google Sheet\n📋 Full archive: https://docs.google.com/spreadsheets/d/1VhI_JzDLAwvZlSqoHTCbl0gnMKxDLCbHzbv-b2Ur8m0/edit`
  }
}];

const items = $input.all();

// Separate stats item from job items
const statsItem = items.find(i => i.json.__stats);
const jobs = items.filter(i => !i.json.__stats);

// Sort by DE-fit score (descending) — already sorted, but make sure
jobs.sort((a, b) => b.json.deFitScore - a.json.deFitScore);

// Pick 1 job per company, max 15 total
const SHORTLIST_SIZE = 15;
const seenCompanies = new Set();
const shortlist = [];
const archive = [];

for (const item of jobs) {
  const company = item.json.company;
  if (!seenCompanies.has(company) && shortlist.length < SHORTLIST_SIZE) {
    shortlist.push({ ...item, json: { ...item.json, shortlisted: true } });
    seenCompanies.add(company);
  } else {
    archive.push({ ...item, json: { ...item.json, shortlisted: false } });
  }
}

console.log(`Shortlist: ${shortlist.length}, Archive: ${archive.length}`);

// Output: shortlist items first, then archive items, then stats
const output = [...shortlist, ...archive];
if (statsItem) {
  output.push({
    json: {
      __stats: {
        ...statsItem.json.__stats,
        shortlistSize: shortlist.length,
        archiveSize: archive.length,
        companiesInShortlist: seenCompanies.size
      }
    }
  });
}

return output;

const items = $input.all();
const results = [];

const noSponsorPatterns = [
  /\b(cannot|unable|will not|do not|won['']t|don['']t)\s+(provide|offer|sponsor)/i,
  /no\s+(visa\s+)?sponsorship/i,
  /(must\s+be|requires?)\s+(authorized|legally\s+able)\s+to\s+work\s+(in\s+the\s+)?(US|United\s+States|U\.S\.?)\s+(without|for\s+any\s+employer)/i,
  /(US\s+Citizen(ship)?|permanent\s+residen[ct])\s+(only|required)/i,
  /not\s+(eligible|able|available)\s+(for|to\s+provide)\s+(visa|H-?1B|sponsorship)/i,
  /sponsorship\s+(is\s+)?not\s+(available|provided|offered)/i,
  /will\s+not\s+sponsor/i,
];

const requiresClearancePatterns = [
  /security\s+clearance/i,
  /\btop\s+secret\b/i,
  /\bts\/sci\b/i,
  /\bsecret\s+clearance\b/i,
];

for (const item of items) {
  const jd = item.json.jdText || '';

  const noSponsorHit = noSponsorPatterns.some(rx => rx.test(jd));
  const clearanceHit = requiresClearancePatterns.some(rx => rx.test(jd));

  let sponsorshipStatus;
  if (noSponsorHit) sponsorshipStatus = '🚫 No sponsorship';
  else if (clearanceHit) sponsorshipStatus = '🚫 Requires clearance';
  else sponsorshipStatus = '🟢 Likely sponsors';

  results.push({
    json: {
      ...item.json,
      sponsorshipStatus,
      sponsorshipBlocked: noSponsorHit || clearanceHit
    }
  });
}

return results;

