const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const llmRaw = items[i].json;

  // Find the text content in Claude's response
  let text = llmRaw.content?.[0]?.text 
    || llmRaw.message?.content 
    || llmRaw.text 
    || '';

  text = text.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();

  let analysis = {};
  try {
    analysis = JSON.parse(text);
  } catch (e) {
    // If Claude returned non-JSON, save as a default
    analysis = {
      fit_score: 0,
      decision: 'skip',
      skills_match: 'Parse error: ' + text.slice(0, 100),
      level_match: '',
      red_flags: ['JSON parse failed'],
      tailoring_strategy: '',
      key_keywords: []
    };
  }

  // Carry forward all the original job data + add Claude analysis
  const originalJob = $('Check Sponsorship').itemMatching(i).json;

  results.push({
    json: {
      ...originalJob,
      claude_fit_score: analysis.fit_score,
      claude_decision: analysis.decision,
      skills_match: analysis.skills_match,
      level_match: analysis.level_match,
      red_flags: (analysis.red_flags || []).join(' | '),
      tailoring_strategy: analysis.tailoring_strategy,
      key_keywords: (analysis.key_keywords || []).join(', ')
    }
  });
}

return results;
